function renderFedWatch(r){
 var d=r&&r.data||{},re=(d.reconstructed||[])[0]||null,inv=d.thirdParty&&d.thirdParty.investing&&d.thirdParty.investing[0]||null,effr=d.effr||{},yf=d.yahooFrontFuture||{},st=$('fedwatchState');
 if(st){st.textContent=d.ok?'ACTIF':'DÉGRADÉ';st.className='fedwatchState '+(d.ok?'ok':'warn');if(d.ok&&d.warnings&&d.warnings.length)st.title='Sources secondaires en avertissement : '+d.warnings.join(' · ');else st.title='';}
 if($('fedwatchMeetingDate'))$('fedwatchMeetingDate').textContent=re&&re.meetingDate||inv&&inv.meetingDate||(d.calendar&&d.calendar[0]&&d.calendar[0].date)||'--';
 if($('fedwatchEffr'))$('fedwatchEffr').textContent=isFinite(+effr.rate)?(+effr.rate).toFixed(2)+' %':'--';
 if($('fedwatchTarget'))$('fedwatchTarget').textContent='Target '+rateRange(effr.targetLow,effr.targetHigh);
 if($('fedwatchFuture'))$('fedwatchFuture').textContent=re&&isFinite(+re.futurePrice)?(+re.futurePrice).toFixed(3):(isFinite(+yf.price)?(+yf.price).toFixed(3):'--');
 if($('fedwatchFutureMeta'))$('fedwatchFutureMeta').textContent=re?'Contrat associé à la réunion · Investing':'ZQ=F retardé · Yahoo Finance';
 if($('fedwatchMethod'))$('fedwatchMethod').textContent=re?(re.method||'IA-TB'):'Source tierce uniquement';
 var ph=$('fedwatchProbabilities'),arr=re&&re.probabilities&&re.probabilities.length?re.probabilities:(inv&&inv.probabilities||[]);
 if(ph)ph.innerHTML=arr.length?arr.map(function(x){var p=Math.max(0,Math.min(100,+x.probability||0));return'<div class="fedwatchProbRow"><div><b>'+esc(rateRange(x.targetLow,x.targetHigh))+'</b><span>'+esc(pct1(p))+'</span></div><div class="fedwatchBar"><i style="width:'+p.toFixed(2)+'%"></i></div></div>'}).join(''):'<div class="fedwatchEmpty">Aucune probabilité exploitable.</div>';
 var sh=$('fedwatchSources'),src=d.sources||[];
 if(sh)sh.innerHTML=src.length?src.map(function(x){var data=x&&x.data||{},meta='',label='';if(x&&x.name&&/New York Fed/.test(x.name)&&data.rate!=null)meta='EFFR '+data.rate+' % · '+(data.date||'');else if(x&&x.name&&/Yahoo/.test(x.name)&&data.price!=null)meta='ZQ '+data.price+(x.stale?' · cache conservé':'');else if(x&&x.name&&/Investing/.test(x.name)&&Array.isArray(data))meta=data.length+' réunion(s)';else if(x&&x.name&&/MacroMicro/.test(x.name))meta=x.ok?'Accessible':'Validation indisponible';else if(x&&x.name&&/Calendar/.test(x.name)&&Array.isArray(data))meta=data.length+' réunion(s)';if(x&&x.ok)label=x.stale?'WARN':'OK';else label=x&&x.role==='VALIDATION_ONLY'?'WARN':'ERROR';return'<div class="fedwatchSource '+fedwatchSourceClass(x)+'"><i></i><div><b>'+esc(x.name||'Source')+'</b><small>'+esc((x.role==='VALIDATION_ONLY'?'Validation · ':'Critique · ')+(meta||(x.error||x.transport||'')))+'</small></div><strong>'+label+'</strong></div>'}).join(''):'<div class="fedwatchEmpty">Aucune source.</div>';
 if($('fedwatchUpdated'))$('fedwatchUpdated').textContent='Dernière mise à jour · '+(d.generatedAt?dt(d.generatedAt):'--')+(re&&re.validationMaePoints!=null?' · écart validation moyen '+pct1(re.validationMaePoints):'');
}
function loadFedWatch(force){
 var req=force?cpWrite('fundamental.fedwatch.refresh',{}):cpRead('fundamental.fedwatch.get',{});
 return req.then(function(r){renderFedWatch(r);if(force&&r&&r.data&&r.data.ok)notice(r.data.warnings&&r.data.warnings.length?'FedWatch actualisé · sources de validation en avertissement':'FedWatch actualisé','ok');return r}).catch(function(e){var s=$('fedwatchState');if(s){s.textContent='ERROR';s.className='fedwatchState bad'}var ph=$('fedwatchProbabilities');if(ph)ph.innerHTML='<div class="fedwatchEmpty bad">'+esc(e.message)+'</div>';if(force){notice('Actualisation FedWatch impossible : '+String(e.message||e),'bad');throw e}return null});
}

function calMonthLabel(d){return d.toLocaleDateString(LANG==='fr'?'fr-FR':'en-US',{month:'long',year:'numeric'}).replace(/^./,function(x){return x.toUpperCase()})}
function calIso(y,m,d){return y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0')}
function calIcon(e){if(!e)return'•';if(e.calendar==='FED_FOMC')return'★';if(e.calendar==='CME_EXPIRATIONS')return'⏱';return'●'}
function calClass(e){if(!e)return'';if(e.calendar==='FED_FOMC')return'fed';if(e.calendar==='CME_EXPIRATIONS')return'expiry';return'cme'}
function calEventText(e){if(!e)return'';if(e.calendar==='CME_EXPIRATIONS'){var p=e.product||e.globexCode||'';return (e.tradingEvent||e.event||'Expiration')+(p?' · '+p:'')}return e.event||'Événement'}
function filterCmeEvents(a){return(a||[]).filter(function(e){if(CME_CAL_FILTER==='ECONOMIC')return e.calendar==='FINANCE_CALENDAR'||e.calendar==='CME_ECONOMIC_RELEASES';if(CME_CAL_FILTER==='EXPIRATION')return e.calendar==='CME_EXPIRATIONS';return e.calendar==='FINANCE_CALENDAR'||e.calendar==='CME_ECONOMIC_RELEASES'||e.calendar==='CME_EXPIRATIONS'})}
function renderMonthCalendar(hostId,month,events){
 var host=$(hostId);if(!host)return;var y=month.getFullYear(),m=month.getMonth(),days=new Date(y,m+1,0).getDate(),first=(new Date(y,m,1).getDay()+6)%7,by={};(events||[]).forEach(function(e){if(!e.date||e.date.slice(0,7)!==calIso(y,m,1).slice(0,7))return;(by[e.date]||(by[e.date]=[])).push(e)});
 var names=LANG==='fr'?['L','M','M','J','V','S','D']:['M','T','W','T','F','S','S'],html=names.map(function(x){return'<div class="calendarDow">'+x+'</div>'}).join('');
 for(var z=0;z<first;z++)html+='<div class="calendarDay emptyDay"></div>';
 var today=new Date(),todayIso=calIso(today.getFullYear(),today.getMonth(),today.getDate());
 for(var d=1;d<=days;d++){var iso=calIso(y,m,d),ev=by[iso]||[],cls=iso===todayIso?' today':'',dots=ev.slice(0,4).map(function(e){return'<i class="'+calClass(e)+'" title="'+esc(calEventText(e))+'"></i>'}).join('');html+='<div class="calendarDay'+cls+(ev.length?' hasEvents':'')+'" data-calendar-date="'+iso+'"><span>'+d+'</span><div class="calendarDots">'+dots+'</div>'+(ev.length>4?'<small>+'+(ev.length-4)+'</small>':'')+'</div>'}
 host.innerHTML=html;
}
